/* Kinderansicht: eigene, ortsbezogene Illustrationen (als Code gezeichnet) */
const C={sky:"#BDE4F7",dusk:"#FFC9A8",night:"#2B2D52",wall:"#FFE9C7",wall2:"#E6E0FF",wall3:"#DFF3EA",grass:"#8FD18A",grass2:"#5DB85B",dgreen:"#3E9B5B",sun:"#FFC93C",red:"#F25F4C",dred:"#B23A2E",orange:"#FF9F43",blue:"#3A86FF",navy:"#1D3557",purple:"#8E6CEF",pink:"#FF7EB6",brown:"#9C6644",dbrown:"#6B4226",wood:"#D49A5E",white:"#FFFFFF",dark:"#2B2D42",water:"#4CC9F0",water2:"#2E9BD6",sand:"#F4D58D",grey:"#AEB8C6",dgrey:"#6B7280",teal:"#2A9D8F",yellow:"#FFD166",floor:"#E4B47E",moor:"#8A7A4A",brick:"#B5543A",copper:"#5FA88A",cream:"#FFF6E0"};
const G=(x,y,s,inner,r=0)=>`<g transform="translate(${x} ${y})${r?` rotate(${r})`:""} scale(${s})">${inner}</g>`;
const W=(...a)=>a.join("");
/* Hintergründe */
const sky=(c=C.sky)=>`<rect width="200" height="120" fill="${c}"/>`;
const sunS=(x=172,y=20,r=10)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${C.sun}"/>`;
const cloud=(x,y,s=1)=>G(x,y,s,`<g fill="#fff" opacity=".95"><ellipse rx="14" ry="6"/><ellipse cx="9" cy="-4" rx="9" ry="6"/><ellipse cx="-8" cy="-2" rx="7" ry="5"/></g>`);
const day=(c)=>sky(c)+sunS()+cloud(36,20)+cloud(118,14,.8);
const hill=(y=92,c=C.grass)=>`<path d="M0 ${y} Q50 ${y-8} 100 ${y-2} T200 ${y-4} V120 H0Z" fill="${c}"/>`;
const flat=(y=94,c=C.floor)=>`<rect y="${y}" width="200" height="${120-y}" fill="${c}"/>`;
const sea=(y=80,c=C.water2)=>`<rect y="${y}" width="200" height="${120-y}" fill="${c}"/><path d="M0 ${y+8} Q12 ${y+3} 25 ${y+8} T50 ${y+8} T75 ${y+8} T100 ${y+8} T125 ${y+8} T150 ${y+8} T175 ${y+8} T200 ${y+8}" stroke="#fff" stroke-width="2" fill="none" opacity=".6"/>`;
const indoor=(w=C.wall,f=C.floor)=>sky(w)+flat(94,f);
const stars=()=>[[20,14],[60,26],[96,10],[140,22],[184,12],[120,40],[30,44]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="1.4" fill="#FFE9A8"/>`).join("");
/* Natur */
const tree=(x,y,s=1,c=C.grass2)=>G(x,y,s,`<rect x="-2.5" y="-14" width="5" height="14" fill="${C.brown}"/><circle cy="-22" r="13" fill="${c}"/><circle cx="-7" cy="-16" r="8" fill="${c}"/><circle cx="7" cy="-16" r="8" fill="${c}"/>`);
const pine=(x,y,s=1)=>G(x,y,s,`<rect x="-2" y="-8" width="4" height="8" fill="${C.brown}"/><path d="M0 -44 L14 -8 H-14Z" fill="${C.dgreen}"/><path d="M0 -50 L10 -26 H-10Z" fill="#4DB06A"/>`);
const birch=(x,y,s=1)=>G(x,y,s,`<rect x="-2" y="-34" width="4" height="34" fill="#fff"/><path d="M-2 -28 h3 M-2 -18 h2 M0 -10 h2" stroke="${C.dark}" stroke-width="1.2"/><ellipse cy="-38" rx="10" ry="13" fill="#9BD36A"/>`);
const palm=(x,y,s=1)=>G(x,y,s,`<path d="M0 0 C2 -14 -2 -26 2 -40" stroke="${C.brown}" stroke-width="4" fill="none"/><g fill="${C.grass2}"><path d="M2 -40 C14 -46 24 -40 28 -32 C18 -38 10 -38 2 -40Z"/><path d="M2 -40 C-10 -46 -20 -40 -24 -32 C-14 -38 -6 -38 2 -40Z"/><path d="M2 -40 C8 -52 18 -54 24 -50 C14 -48 8 -46 2 -40Z"/><path d="M2 -40 C-4 -52 -14 -54 -20 -50 C-10 -48 -4 -46 2 -40Z"/></g>`);
const bush=(x,y,s=1,c=C.grass2)=>G(x,y,s,`<circle cx="-6" cy="-5" r="7" fill="${c}"/><circle cx="5" cy="-6" r="8" fill="${c}"/><circle cy="-10" r="7" fill="${c}"/>`);
const flower=(x,y,c=C.pink,s=1)=>G(x,y,s,`<line y1="0" y2="-14" stroke="${C.grass2}" stroke-width="2"/>${[0,72,144,216,288].map(a=>`<circle cx="${(5*Math.cos(a*Math.PI/180)).toFixed(1)}" cy="${(-14+5*Math.sin(a*Math.PI/180)).toFixed(1)}" r="3.6" fill="${c}"/>`).join("")}<circle cy="-14" r="3" fill="${C.sun}"/>`);
const flowers=(y=100,n=7)=>Array.from({length:n},(_,i)=>flower(14+i*(172/(n-1)),y+(i%2)*4,[C.pink,C.yellow,C.purple,C.red,C.orange][i%5])).join("");
const autumn=(x,y,s=1)=>tree(x,y,s,C.orange);
const mushroom=(x,y,s=1)=>G(x,y,s,`<rect x="-3" y="-9" width="6" height="9" fill="#fff"/><path d="M-10 -8 Q0 -22 10 -8Z" fill="${C.red}"/><circle cx="-4" cy="-12" r="1.6" fill="#fff"/><circle cx="3" cy="-14" r="1.6" fill="#fff"/>`);
const reeds=(x,y,s=1)=>G(x,y,s,`<g stroke="${C.dgreen}" stroke-width="1.6">${[-6,-2,2,6].map(d=>`<line x1="${d}" y1="0" x2="${d*1.4}" y2="-20"/>`).join("")}</g><g fill="${C.dbrown}">${[-8,3].map(d=>`<rect x="${d}" y="-24" width="3" height="8" rx="1.5"/>`).join("")}</g>`);
const cotton=(x,y)=>G(x,y,1,`<line y2="-10" stroke="${C.dgreen}" stroke-width="1.4"/><circle cy="-12" r="3" fill="#fff"/>`);
const dunes=(y=96)=>`<path d="M0 ${y} Q30 ${y-26} 60 ${y-6} Q90 ${y-30} 130 ${y-4} Q160 ${y-22} 200 ${y-2} V120 H0Z" fill="${C.sand}"/><path d="M0 ${y+6} Q30 ${y-14} 60 ${y+4} Q90 ${y-18} 130 ${y+6} Q160 ${y-10} 200 ${y+8} V120 H0Z" fill="#EBC46E"/>`;
const stream=()=>`<path d="M0 104 C40 96 70 112 110 102 S170 96 200 104 V114 C170 106 140 114 110 110 S40 106 0 114Z" fill="${C.water}"/>`;
const bridge=(x,y)=>G(x,y,1,`<path d="M-24 0 Q0 -14 24 0" stroke="${C.wood}" stroke-width="5" fill="none"/><path d="M-22 -4 Q0 -20 22 -4" stroke="${C.dbrown}" stroke-width="2" fill="none"/>${[-16,-8,0,8,16].map(d=>`<line x1="${d}" y1="${-Math.abs(14-Math.abs(d))*0.6-6}" x2="${d}" y2="${-Math.abs(14-Math.abs(d))*0.4}" stroke="${C.dbrown}" stroke-width="1.5"/>`).join("")}`);
const boardwalk=(y=98)=>`<path d="M20 ${y+16} L90 ${y} H110 L180 ${y+16}Z" fill="${C.wood}"/>${[0,1,2,3,4].map(i=>`<line x1="${30+i*35}" y1="${y+16}" x2="${94+i*3}" y2="${y}" stroke="${C.dbrown}" stroke-width="1" opacity=".5"/>`).join("")}`;
const windmill=(x,y,s=1)=>G(x,y,s,`<rect x="-1.5" y="-50" width="3" height="50" fill="#fff"/><g transform="translate(0 -50)" stroke="#fff" stroke-width="3" stroke-linecap="round"><line y2="-20"/><line x2="17" y2="10"/><line x2="-17" y2="10"/></g><circle cy="-50" r="2.5" fill="${C.grey}"/>`);
const rainbowArc=()=>`<g fill="none" stroke-width="4" opacity=".7"><path d="M20 90 A80 70 0 0 1 180 90" stroke="${C.red}"/><path d="M26 90 A74 64 0 0 1 174 90" stroke="${C.yellow}"/><path d="M32 90 A68 58 0 0 1 168 90" stroke="${C.blue}"/></g>`;
/* Tiere */
const sheep=(x,y,s=1)=>G(x,y,s,`<g stroke="${C.dark}" stroke-width="3"><line x1="-8" y1="-6" x2="-8" y2="0"/><line x1="8" y1="-6" x2="8" y2="0"/></g><g fill="#fff">${[[-10,-12],[-3,-15],[5,-15],[11,-12],[0,-9],[-7,-8],[7,-8]].map(([a,b])=>`<circle cx="${a}" cy="${b}" r="6.5"/>`).join("")}</g><ellipse cx="-18" cy="-16" rx="5.5" ry="6.5" fill="${C.dark}"/><circle cx="-19.5" cy="-17.5" r="1.2" fill="#fff"/>`);
const goat=(x,y,s=1,c="#fff")=>G(x,y,s,`<rect x="-14" y="-20" width="26" height="12" rx="6" fill="${c}" stroke="${C.dgrey}" stroke-width=".8"/><g stroke="${C.dgrey}" stroke-width="3"><line x1="-10" y1="-9" x2="-10" y2="0"/><line x1="8" y1="-9" x2="8" y2="0"/></g><path d="M10 -18 L18 -30 L22 -20Z" fill="${c}" stroke="${C.dgrey}" stroke-width=".8"/><path d="M16 -28 l-4 -8 M19 -28 l2 -8" stroke="${C.dark}" stroke-width="1.6"/><path d="M19 -21 l1 5" stroke="${C.dgrey}" stroke-width="2"/><circle cx="18" cy="-25" r="1.2" fill="${C.dark}"/>`);
const deer=(x,y,s=1)=>G(x,y,s,`<rect x="-16" y="-24" width="30" height="12" rx="6" fill="${C.brown}"/><g fill="#fff" opacity=".8"><circle cx="-8" cy="-20" r="1.3"/><circle cx="-2" cy="-17" r="1.3"/><circle cx="4" cy="-20" r="1.3"/></g><g stroke="${C.brown}" stroke-width="3"><line x1="-12" y1="-13" x2="-12" y2="0"/><line x1="10" y1="-13" x2="10" y2="0"/></g><path d="M12 -22 L20 -38 L26 -34 L18 -20Z" fill="${C.brown}"/><circle cx="22" cy="-35" r="1.2" fill="${C.dark}"/><path d="M20 -40 l-4 -10 M18 -46 l-5 -1 M23 -40 l4 -10 M25 -46 l5 -2" stroke="${C.dbrown}" stroke-width="1.6" stroke-linecap="round"/>`);
const boar=(x,y,s=1)=>G(x,y,s,`<ellipse cx="0" cy="-12" rx="17" ry="10" fill="#5B4636"/><path d="M12 -18 L26 -10 L24 -4 L12 -6Z" fill="#5B4636"/><circle cx="18" cy="-13" r="1.2" fill="#fff"/><path d="M23 -7 l3 -3" stroke="#fff" stroke-width="1.5"/><g stroke="#5B4636" stroke-width="3"><line x1="-10" y1="-4" x2="-10" y2="0"/><line x1="8" y1="-4" x2="8" y2="0"/></g><path d="M-14 -20 l2 -4 l2 3 l2 -4 l2 3 l2 -4 l2 4" stroke="#3E2F24" stroke-width="1.5" fill="none"/>`);
const cow=(x,y,s=1,c="#3B2B22")=>G(x,y,s,`<rect x="-18" y="-24" width="34" height="16" rx="7" fill="${c}"/><g stroke="${c}" stroke-width="3.5"><line x1="-13" y1="-10" x2="-13" y2="0"/><line x1="11" y1="-10" x2="11" y2="0"/></g><rect x="14" y="-28" width="12" height="14" rx="5" fill="${c}"/><path d="M14 -28 l-4 -4 M26 -28 l4 -4" stroke="${C.wood}" stroke-width="2"/><ellipse cx="20" cy="-15" rx="5" ry="3" fill="#D9A68A"/><circle cx="17" cy="-23" r="1.2" fill="#fff"/><circle cx="23" cy="-23" r="1.2" fill="#fff"/>`);
const spotcow=(x,y,s=1)=>G(x,y,s,cow(0,0,1,"#fff")+`<g fill="${C.dark}"><ellipse cx="-8" cy="-18" rx="5" ry="3.5"/><ellipse cx="5" cy="-14" rx="4" ry="3"/></g>`);
const pig=(x,y,s=1,c="#F7A8B8")=>G(x,y,s,`<ellipse cy="-11" rx="15" ry="10" fill="${c}"/><circle cx="14" cy="-14" r="7" fill="${c}"/><ellipse cx="20" cy="-13" rx="3" ry="2.5" fill="#E07A93"/><circle cx="13" cy="-17" r="1.1" fill="${C.dark}"/><path d="M10 -20 l2 -5 l3 4" fill="${c}"/><g stroke="${c}" stroke-width="3"><line x1="-8" y1="-3" x2="-8" y2="0"/><line x1="7" y1="-3" x2="7" y2="0"/></g><path d="M-15 -12 q-5 -2 -3 -6" stroke="#E07A93" stroke-width="1.5" fill="none"/>`);
const chicken=(x,y,s=1,c="#fff")=>G(x,y,s,`<ellipse cy="-8" rx="8" ry="6.5" fill="${c}" stroke="${C.dgrey}" stroke-width=".6"/><circle cx="7" cy="-15" r="4.5" fill="${c}" stroke="${C.dgrey}" stroke-width=".6"/><path d="M11 -15 l4 1.5 l-4 1.5z" fill="${C.orange}"/><path d="M5 -20 q2 -3 4 0 q2 -3 3 1" fill="${C.red}"/><circle cx="8" cy="-16" r=".9" fill="${C.dark}"/><path d="M-2 -2 v3 M3 -2 v3" stroke="${C.orange}" stroke-width="1.5"/><path d="M-8 -10 q-6 -6 -2 -10" stroke="${C.dgrey}" stroke-width="1" fill="${c}"/>`);
const duck=(x,y,s=1)=>G(x,y,s,`<ellipse cy="-5" rx="12" ry="6" fill="#fff"/><circle cx="9" cy="-13" r="5" fill="#2F8F5B"/><path d="M13 -13 L19 -12 L13 -10Z" fill="${C.orange}"/><circle cx="10" cy="-14" r="1" fill="${C.dark}"/>`);
const owl=(x,y,s=1)=>G(x,y,s,`<ellipse cy="-14" rx="10" ry="14" fill="${C.brown}"/><ellipse cy="-10" rx="6" ry="8" fill="#E8C9A0"/><circle cx="-4" cy="-20" r="4.5" fill="#fff"/><circle cx="4" cy="-20" r="4.5" fill="#fff"/><circle cx="-4" cy="-20" r="2" fill="${C.dark}"/><circle cx="4" cy="-20" r="2" fill="${C.dark}"/><path d="M-1 -16 L0 -13 L1 -16Z" fill="${C.orange}"/><path d="M-9 -26 l2 -5 l3 4 M9 -26 l-2 -5 l-3 4" fill="${C.brown}"/>`);
const eagle=(x,y,s=1)=>G(x,y,s,`<path d="M0 0 C-14 -8 -30 -6 -40 2 C-28 -2 -16 2 -6 6Z M0 0 C14 -8 30 -6 40 2 C28 -2 16 2 6 6Z" fill="${C.dbrown}"/><ellipse cy="2" rx="6" ry="9" fill="${C.dbrown}"/><circle cy="-8" r="4.5" fill="#fff"/><path d="M3 -8 l4 2 l-4 1z" fill="${C.yellow}"/>`);
const bird=(x,y,s=1)=>G(x,y,s,`<path d="M-6 0 q3 -4 6 0 q3 -4 6 0" stroke="${C.dark}" stroke-width="1.8" fill="none" stroke-linecap="round"/>`);
const crane=(x,y,s=1)=>G(x,y,s,`<ellipse cy="-26" rx="12" ry="6" fill="${C.grey}"/><path d="M8 -28 C14 -40 10 -50 16 -52" stroke="${C.grey}" stroke-width="3" fill="none"/><circle cx="16" cy="-52" r="3" fill="${C.dark}"/><circle cx="16" cy="-54" r="1.2" fill="${C.red}"/><path d="M19 -52 l7 2" stroke="${C.dark}" stroke-width="1.5"/><path d="M-12 -26 q-6 2 -8 6" stroke="${C.dark}" stroke-width="3" fill="none"/><g stroke="${C.dark}" stroke-width="1.5"><line x1="-2" y1="-20" x2="-4" y2="0"/><line x1="2" y1="-20" x2="4" y2="0"/></g>`);
const horse=(x,y,s=1,c="#FFFFFF")=>G(x,y,s,`<rect x="-18" y="-30" width="34" height="14" rx="7" fill="${c}" stroke="${C.dgrey}" stroke-width=".8"/><g stroke="${C.dgrey}" stroke-width="3"><line x1="-14" y1="-17" x2="-15" y2="0"/><line x1="-6" y1="-17" x2="-5" y2="0"/><line x1="6" y1="-17" x2="6" y2="0"/><line x1="12" y1="-17" x2="14" y2="0"/></g><path d="M12 -28 L22 -44 L30 -38 L20 -24Z" fill="${c}" stroke="${C.dgrey}" stroke-width=".8"/><path d="M14 -32 L20 -44" stroke="${C.dbrown}" stroke-width="3"/><path d="M-18 -26 q-8 4 -6 14" stroke="${C.dbrown}" stroke-width="3" fill="none"/>`);
const rider=(x,y,s=1)=>G(x,y,s,`<path d="M-2 -30 V-46 M-2 -42 L8 -36 M-2 -40 L-10 -34" stroke="${C.wood}" stroke-width="3" stroke-linecap="round"/><circle cx="-2" cy="-50" r="4" fill="${C.wood}"/><path d="M-6 -54 h8 l-4 -6z" fill="${C.dark}"/><path d="M-2 -54 l1 -8 l2 1" stroke="${C.red}" stroke-width="2" fill="none"/>`);
const fox=(x,y,s=1)=>G(x,y,s,`<ellipse cy="-10" rx="13" ry="7" fill="${C.orange}"/><path d="M10 -12 L20 -22 L24 -14 L16 -8Z" fill="${C.orange}"/><path d="M18 -20 l-1 -6 l3 4 M21 -18 l3 -5 l0 5" fill="${C.orange}"/><circle cx="19" cy="-16" r="1" fill="${C.dark}"/><path d="M-12 -10 C-24 -14 -28 -4 -20 -2 C-16 -6 -14 -8 -12 -8Z" fill="${C.orange}"/><circle cx="-24" cy="-6" r="2.5" fill="#fff"/><g stroke="${C.dbrown}" stroke-width="2.5"><line x1="-6" y1="-4" x2="-6" y2="0"/><line x1="6" y1="-4" x2="6" y2="0"/></g>`);
const bear=(x,y,s=1)=>G(x,y,s,`<ellipse cy="-14" rx="18" ry="12" fill="${C.dbrown}"/><circle cx="16" cy="-22" r="8" fill="${C.dbrown}"/><circle cx="13" cy="-29" r="3" fill="${C.dbrown}"/><circle cx="20" cy="-29" r="3" fill="${C.dbrown}"/><ellipse cx="21" cy="-20" rx="3.5" ry="2.5" fill="#C9A27E"/><circle cx="17" cy="-24" r="1.1" fill="#fff"/><g stroke="${C.dbrown}" stroke-width="5"><line x1="-10" y1="-4" x2="-10" y2="0"/><line x1="8" y1="-4" x2="8" y2="0"/></g>`);
const monkey=(x,y,s=1)=>G(x,y,s,`<circle cy="-20" r="7" fill="${C.brown}"/><ellipse cy="-18" rx="5" ry="4" fill="#E8C9A0"/><circle cx="-8" cy="-21" r="3" fill="${C.brown}"/><circle cx="8" cy="-21" r="3" fill="${C.brown}"/><ellipse cy="-6" rx="6" ry="8" fill="${C.brown}"/><path d="M5 -4 q10 2 8 -10" stroke="${C.brown}" stroke-width="2" fill="none"/>`);
const bee=(x,y,s=1)=>G(x,y,s,`<ellipse rx="6" ry="4.5" fill="${C.yellow}"/><path d="M-2 -4 V4 M2 -4 V4" stroke="${C.dark}" stroke-width="1.8"/><ellipse cx="-1" cy="-6" rx="4" ry="2.5" fill="#fff" opacity=".85"/><ellipse cx="3" cy="-6" rx="3" ry="2" fill="#fff" opacity=".85"/>`);
const hive=(x,y,s=1)=>G(x,y,s,`<rect x="-14" y="-28" width="28" height="28" fill="${C.yellow}"/><rect x="-16" y="-32" width="32" height="5" fill="${C.wood}"/><path d="M-14 -18 H14 M-14 -9 H14" stroke="${C.wood}" stroke-width="2"/><rect x="-4" y="-5" width="8" height="3" fill="${C.dark}"/>`);
const cat=(x,y,s=1,c=C.orange)=>G(x,y,s,`<ellipse cy="-9" rx="10" ry="8" fill="${c}"/><circle cy="-22" r="7" fill="${c}"/><path d="M-6 -26 l1 -7 l5 4 M6 -26 l-1 -7 l-5 4" fill="${c}"/><circle cx="-2.5" cy="-23" r="1" fill="${C.dark}"/><circle cx="2.5" cy="-23" r="1" fill="${C.dark}"/><path d="M-1 -20 h2" stroke="${C.pink}" stroke-width="1.5"/><path d="M9 -6 q10 -2 8 -14" stroke="${c}" stroke-width="3" fill="none" stroke-linecap="round"/>`);
const whale=(x,y,s=1)=>G(x,y,s,`<path d="M-40 0 C-40 -20 10 -24 30 -10 C40 -4 46 -14 50 -20 C50 -10 46 0 36 2 C10 8 -40 12 -40 0Z" fill="${C.navy}"/><circle cx="-28" cy="-6" r="1.8" fill="#fff"/><path d="M-40 2 Q-20 6 0 4" stroke="#fff" stroke-width="1.5" fill="none" opacity=".6"/>`);
const skeleton=(x,y,s=1)=>G(x,y,s,`<path d="M-50 0 C-30 -18 20 -18 50 -4" stroke="#F4EAD2" stroke-width="3" fill="none"/>${Array.from({length:12},(_,i)=>{const t=-44+i*8;return `<path d="M${t} ${-9-Math.sin((i+1)/13*Math.PI)*6} v${8+Math.sin((i+1)/13*Math.PI)*8}" stroke="#F4EAD2" stroke-width="2"/>`}).join("")}<ellipse cx="-50" cy="0" rx="10" ry="5" fill="#F4EAD2"/><path d="M48 -4 l8 -6 M48 -4 l8 4" stroke="#F4EAD2" stroke-width="2.5"/>`);
const elephant=(x,y,s=1)=>G(x,y,s,`<ellipse cy="-22" rx="22" ry="15" fill="${C.grey}"/><circle cx="20" cy="-28" r="11" fill="${C.grey}"/><ellipse cx="14" cy="-28" rx="7" ry="9" fill="#9AA5B4"/><path d="M28 -24 C34 -14 30 -4 34 0" stroke="${C.grey}" stroke-width="5" fill="none" stroke-linecap="round"/><circle cx="23" cy="-32" r="1.3" fill="${C.dark}"/><g fill="${C.grey}"><rect x="-16" y="-12" width="7" height="12"/><rect x="8" y="-12" width="7" height="12"/></g>`);
const dino=(x,y,s=1,c=C.teal)=>G(x,y,s,`<path d="M-30 -6 C-20 -10 -10 -26 4 -26 C14 -26 16 -40 22 -50 C26 -56 34 -54 32 -48 C28 -40 26 -30 22 -22 C20 -10 10 -4 -4 -4Z" fill="${c}"/><g fill="${c}"><rect x="-12" y="-8" width="6" height="8"/><rect x="6" y="-8" width="6" height="8"/></g><circle cx="29" cy="-50" r="1.2" fill="#fff"/>`);
const giraffe=(x,y,s=1,c=C.yellow)=>G(x,y,s,`<rect x="-12" y="-26" width="22" height="12" rx="4" fill="${c}"/><path d="M6 -24 L14 -54 L20 -52 L12 -22Z" fill="${c}"/><rect x="11" y="-60" width="12" height="8" rx="3" fill="${c}"/><g stroke="${c}" stroke-width="3"><line x1="-9" y1="-15" x2="-9" y2="0"/><line x1="7" y1="-15" x2="7" y2="0"/></g><g fill="${C.orange}"><rect x="-8" y="-24" width="4" height="4"/><rect x="0" y="-20" width="4" height="4"/><rect x="11" y="-42" width="3" height="3"/></g>`);
/* Gebäude & Landmarken */
const house=(x,y,s=1,c=C.red,r=C.dred)=>G(x,y,s,`<rect x="-14" y="-20" width="28" height="20" fill="${c}"/><path d="M-17 -20 L0 -34 L17 -20Z" fill="${r}"/><rect x="-4" y="-11" width="8" height="11" fill="#fff"/><rect x="-11" y="-16" width="5" height="5" fill="#fff"/><rect x="6" y="-16" width="5" height="5" fill="#fff"/>`);
