function bowlFull(x,y){return G(x,y,1,`<path d="M-20 -14 H20 Q18 0 0 2 Q-18 0 -20 -14Z" fill="${C.teal}"/><ellipse cy="-14" rx="20" ry="5" fill="#9BE0B0"/><circle cx="-6" cy="-16" r="3" fill="${C.red}"/><circle cx="6" cy="-16" r="3" fill="${C.orange}"/>`)}
for(const k of Object.keys(P)) if(/ $/.test(k)||!P[k]().length) delete P[k];
/* Zuordnung der übrigen Orte über Stichwörter */
function sceneKey(p){const s=(p.n+" "+p.d).toLowerCase();
  const R=[[/eis\b|eisdiele|eisladen|ice cream/,"ice"],[/bäcker|backhus/,"bakery"],[/burger|pizza|pasta/,"food"],[/frühstück|breakfast/,"breakfast"],[/familiencafé|spielecke|spielbereich/,"famcafe"],
   [/spielplatz/,"playground"],[/indoor|spielstadt/,"balls"],[/boulder|kletter/,"climb"],[/park\b|park /,"park"],[/wald|moor|forst/,"forest"],[/hof|obst/,"farm"],[/museum|ausstellung/,"museum"],[/café|cafe|konditorei|kuchen/,"cafe"]];
  for(const [re,k] of R) if(re.test(s)) return k; return {cafe:"cafe",natur:"forest",aktiv:"playground",museum:"museum",ausflug:"park",hof:"farm",spiel:"balls",kreativ:"crafts",baden:"pool"}[p.c]||"park"}
const FALL={ice:()=>sky("#FFE3EE")+cone(100,108,1.3),bakery:()=>indoor("#FFF6E0","#E4C9A2")+counter(82)+pretzel(60,82,.8)+bread(140,82,.8),food:()=>indoor("#FFF1E8","#E7C9B2")+burger(70,94,1)+pizza(140,80,.9),
 breakfast:()=>indoor("#F5EFE6","#D9CBB5")+plate(80,94,1.1)+egg(80,90,.7)+cup(150,94,.8),famcafe:()=>indoor("#FFF1E0","#F0D3B0")+softplay(64,96,.6)+cup(160,92,.7),
 playground:generic.playground,balls:generic.balls,climb:()=>indoor(C.wall2,"#C9B8F0")+climbWall(110,96)+climber(106,66,1,C.orange),park:generic.park,forest:generic.forest,
 farm:()=>day()+hill()+barn(70,96,.9)+sheep(140,106,.8),museum:generic.museum,cafe:generic.cafe,crafts:()=>indoor("#FFF3D6","#E4C9A2")+palette(90,90,.8)+brush(160,100,1),pool:()=>sky(C.wall2)+pool(72)+waterslide(20,72,.8)+ring(160,92)};
function sceneSvg(p){const f=P[p.n]||FALL[sceneKey(p)];return `<svg viewBox="0 0 200 120" role="img" aria-label="Zeichnung: ${esc(p.n)}" preserveAspectRatio="xMidYMid slice">${f()}</svg>`}
function sceneOf(p){return P[p.n]?"place":sceneKey(p)}
/* Gruppen für die Kinder-Auswahl */
function kidGroup(p){const s=(p.n+" "+p.d).toLowerCase();
  if(p.c==="hof") return "animals";
  if(/\beis\b|eisdiele|eisladen|ice cream|bäcker|backhus|\bburger|pizza|restaurant|frühstück|wirtshaus|gasthaus|konditorei/.test(s)||(p.c==="cafe"&&!/spielecke|spielbereich|familiencafé|spiellandschaft|familientreff/.test(s))) return "yum";
  if(/indoor|trampolin|kletter|boulder|parkour|bagger|rodelbahn|pumptrack|skate|bowling|minigolf|action|hochseil|sportverein|spielplatz|spielstadt|spielecafé|spielcafé|spielhaus|spielbereich|spielecke|spiellandschaft/.test(s)||p.c==="spiel"||p.c==="aktiv") return "play";
  if(p.c==="baden"||/kanu|kajak|boot|sup-|wasserspiel|geysir|badesee|strand|lagune|planschbecken/.test(s)) return "water";
  if(/tier|zoo|wild|arche|streichel|hühner|vogel|bauernhof|schaf|gehege|weiden|jordsand/.test(s)) return "animals";
  if(p.c==="museum"||p.c==="kreativ"||/flughafen|tunnel|fähre|bunker|lego|kino|theater|bücher|miniatur/.test(s)) return "discover";
  return "nature"}
const KSC=new Proxy({},{get:(_,n)=>["Tüdelband Winsen","Pflanzen-Kölle Gartencenter","LIFE HAMBURG Campus"].includes(n)?1:undefined});
